components.css:
.ds-ui-dropdown {
  z-index: 50;
  min-width: 132px;
  max-width: var(--radix-dropdown-menu-content-available-width);
  max-height: var(--radix-dropdown-menu-content-available-height);
  overflow-y: auto;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  color: var(--ink);
  font-family: inherit;
  box-shadow: 0 2px 6px rgba(24, 24, 27, 0.04);
}

.ds-ui-dropdown__item {
  min-height: 36px;
  display: grid;
  grid-template-columns: 1fr 14px;
  align-items: center;
  gap: 16px;
  padding: 6px 10px;
  border-radius: 3px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
  cursor: default;
  user-select: none;
  outline: none;
}

.ds-ui-dropdown__item[data-state="checked"] { color: var(--ink); }
.ds-ui-dropdown__item[data-highlighted] { color: var(--ink); background: var(--panel); }
.ds-ui-dropdown__item:focus-visible { outline: 2px solid var(--blue); outline-offset: -2px; }
.ds-ui-dropdown__item[data-disabled] { opacity: 0.45; pointer-events: none; }
.ds-ui-dropdown__indicator { display: flex; width: 14px; height: 14px; }
.ds-ui-dropdown__indicator svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }

.ds-language-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 0 4px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #66666e;
  font-size: 14px;
  cursor: pointer;
  transition: color 160ms ease;
}
.ds-language-trigger:hover, .ds-language-trigger[data-state="open"] { color: var(--ink); }
.ds-language-trigger svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.ds-language-trigger[data-state="open"] svg { transform: rotate(180deg); }

.ds-focus-panel {
  position: relative;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  transform-origin: center top;
  transition: transform 200ms ease-out, border-color 200ms ease-out;
}
.ds-focus-panel[data-active="true"] {
  border-color: var(--blue);
  outline: 1px solid var(--blue);
  transform: scale(1.015);
  z-index: 1;
}
.ds-focus-panel__label {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  min-height: 34px;
  border-bottom: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 11px;
}
.ds-focus-panel__label strong { color: var(--ink); font-weight: 600; }
.ds-focus-panel[data-active="true"] > .ds-focus-panel__label { background: var(--blue-soft); color: var(--ink); }
@media (prefers-reduced-motion: reduce) {
  .ds-focus-panel { transition: none; }
  .ds-focus-panel[data-active="true"] { transform: none; }
}
